describe('P&ID validation (09 §6)', () => {
  it('HLT-026: KPIs, chips, tag register, overlay, steps and tag drawers reproduce the prototype', async () => {
    const v = (await getPidValidation('HLT-026'))!;
    const g = G.pid;
    expect([
      [`${v.sheet.documentNumber} rev ${v.sheet.revision}`, `${v.sheet.sheetCount} sheets · ${v.sheet.statusLabel} · ${shortDateYear(v.sheet.issuedOn)}`],
      [v.coverage.inScope, `${v.coverage.overlay} overlay · ${v.coverage.client} client-supplied`], [`${v.coverage.pct}%`, `${v.coverage.linked} / ${v.coverage.inScope} tags`],
      [v.coverage.unmapped, 'Blocks release for construction'], [v.coverage.referenceIssues, 'Not in BOM · outdated · not validated'],
    ]).toEqual(kv(g.kpis));
    const order = ['Linked', 'Unmapped', 'Not in BOM', 'Part not validated', 'Part outdated', 'Part obsolete', 'Client'];
    expect([['All', v.tags.length], ...order.filter((s) => v.tags.some((t) => t.statusLabel === s)).map((s) => [s, v.tags.filter((t) => t.statusLabel === s).length])]).toEqual(g.chips);
    expect(v.tags.map((t) => ({
      tag: t.tag, desc: t.description, kind: t.kindLabel, scope: t.scopeLabel, refText: t.partRef ?? '—', partName: t.partName ?? (t.scope === 'client' ? t.note : ''),
      status: t.statusLabel, actText: `${t.activityCode}${t.activityName ? ' · ' + t.activityName : ''}`, plcText: t.plcLabel ?? '—',
      fbText: t.stateFeedback || (t.role === 'actuator' && (t.plcType === 'P' || t.plcType === 'S') ? 'Missing' : '—'), fbWarn: t.feedbackMissing,
    }))).toEqual(g.rows);
    expect(v.tags.filter((t) => t.scope !== 'keystone').map((t) => t.tag)).toEqual(g.overlay);
    expect(v.steps.map((s) => ({ label: s.label, who: s.who, date: s.dateOn ? d(s.dateOn) : '—', state: s.stateLabel }))).toEqual(g.steps);
    for (const tag of Object.keys(g.drawers)) {
      const t = v.tags.find((x) => x.tag === tag)!;
      // E-6 (R-108): the catalogue search lists the project BOM's articles first; the prototype's 8 are the first of them.
      const c = (await pidCandidates('HLT-026', tag)).rows.filter((x) => x.inBom).slice(0, 8);
      expect(c.map((x) => [x.ref, x.statusLabel]), tag).toEqual(g.drawers[tag].candidates);
      expect([
        ['Reference', t.partRef ?? '—'], ['Part', (t.partName ?? (t.scope === 'client' ? t.note : '')) || '—'], ['Activity', `${t.activityCode}${t.activityName ? ' · ' + t.activityName : ''}`],
        ['PLC', t.plcLabel ?? '—'], ['State feedback', t.stateFeedback || (t.feedbackMissing ? 'Missing' : '—')], ['Sheet', `PID-HLT-026 · sheet ${t.sheet}`],
        ['Scope', t.scope === 'overlay' ? 'Overlay — Keystone sensor on client equipment' : t.scope === 'client' ? 'Client-supplied equipment (free issue)' : 'Keystone supply'],
      ], tag).toEqual(g.drawers[tag].meta);
      expect([t.scope !== 'client', t.status === 'not_in_bom', t.feedbackMissing]).toEqual([g.drawers[tag].canMap, g.drawers[tag].notInBom, g.drawers[tag].fbWarn]);
    }
    expect(v.sheet).toMatchObject({ codexRevision: 'D', codexStatus: 'released' });
    expect(await pidBadgeByProject()).toEqual({ 'HLT-026': 9 });
    expect(await getPidValidation('NDC-031')).toBeNull();
  });
});

// ── Machine types, Settings, Activity & integrations ───────────────────────────────────────────────────

describe('administration (09 §9, 10 §1–2)', () => {
  it('machine types: list, identity, phases, ITP systems, cost categories, REX and KPIs reproduce MT_ALL', async () => {
    const types = await listMachineTypes();
    const g = G.mtypes;
    expect(types.map((t) => ({
      code: t.displayCode, label: t.label, sub: `${t.phases.length} phases · ${t.costCategories.length} cost categories · ${t.itpSystems.length} ITP systems`,
      use: t.projects.length ? `${t.projects.length}${t.projects.length > 1 ? ' projects' : ' project'}` : 'no project', stateText: t.active ? 'Active' : 'Inactive', custom: !t.isStandard,
    }))).toEqual(g.list);
    for (const t of types) {
      const m = g.types[t.displayCode];
      expect({
        code: t.displayCode, label: t.label, desc: t.description, cal: t.calendarLabel, dep: String(t.depositPct), deliv: String(t.deliveryPct), acc: String(t.acceptancePct),
        termsSum: `${t.depositPct + t.deliveryPct + t.acceptancePct} %`, catTotal: f(t.costTotalKeur), phases: t.phases, cats: t.costCategories.map((c) => [c.name, c.typeLabel, String(c.budgetKeur)]),
        itp: t.itpSystems, refs: t.rexReferences.map((r) => ({ name: `${r.analyticCode} · ${r.projectName} · ${r.year}` })),
      }, t.code).toEqual(pickKeys(m, ['code', 'label', 'desc', 'cal', 'dep', 'deliv', 'acc', 'termsSum', 'catTotal', 'phases', 'cats', 'itp', 'refs']));
    }
    expect(types.find((t) => t.code === 'EMP')!.projects.map((p) => p.code)).toEqual(['HLT-026']);
  });

  it('settings: lists, locations, thresholds and KPIs reproduce settingsCards / settingsKpis', async () => {
    const s = await getSettings();
    const g = G.settings;
    const items: Record<string, unknown[]> = {
      locations: s.locations.map((l) => [l.name, l.typeLabel]), skills: s.lists.skills.map((x) => x.label), costCats: s.lists.costCats.map((x) => x.label),
      statuses: s.lists.statuses.map((x) => x.label), riskCats: s.lists.riskCats.map((x) => x.label), delivTypes: s.lists.delivTypes.map((x) => x.label), holidays: s.lists.holidays.map((x) => x.label),
    };
    expect(g.cards.map((c: any) => ({ key: c.key, count: items[c.key].length, items: items[c.key] }))).toEqual(g.cards.map((c: any) => ({ key: c.key, count: c.count, items: c.items })));
    expect(`On track when CPI and SPI ≥ ${s.health.risk} · At risk below ${s.health.risk} · Off track below ${s.health.off}`).toBe(g.healthText);
    expect([
      [s.locations.length, `${new Set(s.locations.map((l) => l.type)).size} types in use`], [s.lists.skills.length, 'Rated 1–5'], [s.lists.costCats.length, 'Per-project overrides allowed'],
      [`${s.health.risk} / ${s.health.off}`, 'At-risk / off-track thresholds'], [s.lists.holidays.length, '2026 · France'],
    ]).toEqual(kv(g.kpis));
    expect(s.lists.locTypes.map((x) => x.code)).toEqual(['central_warehouse', 'workshop', 'site_store', 'consignment', 'quarantine']);
    expect(s.lists.holidays[6]).toEqual({ code: '2026-07-14', label: '14 Jul · Fête nationale' });
  });

  it('activity & integrations: connectors (+ Vigie from the connector layer), imports, audit trail, KPI counts', async () => {
    const conns = await listConnectors();
    const g = G.plumbing;
    // The prototype's connectors with their real state (R-021: A-15, NEW-CURSUS-4): Lucca retired; Cursus and Codex mocks (no
    // last sync, the mirror / index content); Sage X3, the PDM, Outlook, Teams and SMTP "Not connected" (no seeded status,
    // last sync or volume); MS Project keeps its last export.
    // S-11 a, X-6b, I-3c (R-037): the Microsoft 365 rows requalified (Outlook / Teams meetings into Keystone, no channel posts).
    // Delivery 8 (R-027, R-031): the Cursus row says what Keystone now receives (absences, staff directory) instead of the
    // prototype's "approvals only, no personal data imported".
    const SCOPE: Record<string, string> = {
      'Outlook / Exchange': 'Meetings carrying the project code, Outlook / Teams → Keystone (S-11)',
      'Microsoft Teams': 'Teams meetings through the Microsoft 365 app with Outlook, no channel posts',
      Cursus: 'Individual go / no go (visa, vaccination, clearances & badges) · approved leave and absences · staff directory: name, e-mail, matricule, team (R-027, R-031)',
    };
    const expected = g.connectors.filter((r: any) => r.name !== 'Lucca').map((r: any) =>
      r.name === 'Cursus' || r.name === 'Codex' ? { ...r, what: SCOPE[r.name] ?? r.what, st: 'Mock', last: '—' } : r.name === 'MS Project' ? r : { ...r, what: SCOPE[r.name] ?? r.what, st: 'Not connected', last: '—', vol: '' });
    expect(conns.slice(0, 8).map((c) => ({ name: c.name, what: c.dataScope, freq: c.frequency, st: c.statusLabel, last: c.lastSyncAt ? stampText(new Date(c.lastSyncAt)) : '—', vol: c.lastVolume })))
      .toEqual(expected);
    // Deliberate: Vigie (ECOs, NCRs, site HSE) is listed last, its state read from the connector layer (a mock without its API URL).
    expect(conns[8]).toMatchObject({ name: 'Vigie', kind: 'vigie', mode: 'mock', link: 'mock', state: 'mock', status: 'ok', lastSyncAt: null, lastVolume: '6 ECOs · 15 NCRs · 5 HSE items', pending: 0, failed: 0 });
    expect(conns.find((c) => c.name === 'Cursus')).toMatchObject({ kind: 'cursus', mode: 'mock', link: 'mock' });
    // R-021: the prototype's "!" came from Outlook's seeded "Warning · Token expires in 3 days"; no live connector fails.
    expect(await plumbingNavBadge()).toBe('');
    expect((await listImportFormats()).map((x) => ({ name: x.name, desc: x.description, icon: x.icon }))).toEqual(g.imports);
    const audit = (await listAudit({ limit: 50 })).filter((a) => g.audit.some((x: any) => x.obj === a.object && x.change === a.change));
    expect(audit.map((a) => ({ when: a.when, who: a.who, obj: a.object, change: a.change, area: a.area }))).toEqual(g.audit);
    const counts = await getPlumbingCounts();
    // A-12 (chapter 4, 10 OQ4): "Events today" counts the events of the data date (Paris day) — 5 on 25 Sep; the
    // prototype's 6 included an event of 26 Sep.
    expect(g.kpis[0].value).toBe(6);
    // L9-X3: + the four audit rows of the CMR and delivery note the demo files in Codex on 21 Sep (within the last 7 days).
    expect([counts.eventsToday, counts.auditLast7Days]).toEqual([5, g.kpis[3].value + 4]);
  });
});

// ── A-12: "closed this quarter" ───────────────────────────────────────────────────────────────────────────────

describe('quality — "N closed this quarter" counts the data date\'s quarter only (A-12, 07 OQ23)', () => {
  it('a closed NCR whose Vigie closure date falls in another quarter (Q2) is not counted', async () => {
    const db = await getDb();
    const closed = await db.select({ id: vigieNcrs.id, at: vigieNcrs.vigieUpdatedAt }).from(vigieNcrs)
      .where(and(eq(vigieNcrs.projectCode, 'HLT-026'), eq(vigieNcrs.status, 'closed')));
    expect(closed.length).toBeGreaterThan(0);
    const sub = async () => {
      const q = await getQualityScreen('HLT-026');
      return ncrKpis(q.ncrs, q.today, q.dataDate)[0].sub;
    };
    // Seed: every closed NCR was closed in Q3 2026, the data date's quarter (the prototype counted every closed NCR).
    expect(await sub()).toBe(`${closed.length} closed this quarter`);
    await db.update(vigieNcrs).set({ vigieUpdatedAt: new Date('2026-06-15T10:00:00Z') }).where(eq(vigieNcrs.id, closed[0].id));
    try {
      expect(await sub()).toBe(`${closed.length - 1} closed this quarter`);
    } finally {
      await db.update(vigieNcrs).set({ vigieUpdatedAt: closed[0].at }).where(eq(vigieNcrs.id, closed[0].id));
    }
  });
});
